"use client";
import { useState } from "react";
import type { HubState, SchedulingPolicy } from "@/lib/vendor-demo/model";
export function SchedulingPolicyForm({state,save}:{state:HubState;save:(state:HubState,message?:string)=>void}) {
  const [policy,setPolicy]=useState<SchedulingPolicy>(state.scheduling ?? {mode:"single",simultaneous:2,dailyLimit:null});
  return <details className="mt-5 border-t pt-4"><summary className="cursor-pointer text-sm font-semibold">Scheduling policy</summary><form className="mt-3 space-y-3" onSubmit={e=>{e.preventDefault();save({...state,scheduling:policy},"Scheduling policy saved.");}}><label className="block text-sm">Event capacity<select className="hub-input mt-1 w-full" value={policy.mode} onChange={e=>setPolicy({...policy,mode:e.target.value as SchedulingPolicy["mode"]})}><option value="single">One event at a time</option><option value="capacity">Up to N simultaneous events</option><option value="manual">Multiple events, manage manually</option></select></label>{policy.mode === "capacity" && <label className="block text-sm">Simultaneous events<input type="number" min={1} max={100} required className="hub-input mt-1 w-full" value={policy.simultaneous} onChange={e=>setPolicy({...policy,simultaneous:Number(e.target.value)})} /></label>}<label className="block text-sm">Daily event limit (optional)<input className="hub-input mt-1 w-full" type="number" min={1} max={1000} placeholder="No daily limit" value={policy.dailyLimit ?? ""} onChange={e=>setPolicy({...policy,dailyLimit:e.target.value ? Number(e.target.value):null})} /></label><p className="hub-muted text-xs">Confirmed, tentative and held time ranges count toward capacity. Existing events are preserved.</p><button className="hub-primary">Save scheduling policy</button></form></details>;
}
